#include <vector>
#include <unordered_map>
#include <algorithm>

class Solution {
public:
    int findLucky(std::vector<int>& arr) {
        std::unordered_map<int, int> counts;
        for (int x : arr) counts[x]++;
        int lucky = -1;
        for (const auto& [num, freq] : counts) {
            if (num == freq) lucky = std::max(lucky, num);
        }
        return lucky;
    }
};

import java.util.*;

class Solution {
    public int findLucky(int[] arr) {
        Map<Integer, Integer> counts = new HashMap<>();
        for (int x : arr) counts.put(x, counts.getOrDefault(x, 0) + 1);
        int lucky = -1;
        for (Map.Entry<Integer, Integer> e : counts.entrySet()) {
            if (e.getKey().equals(e.getValue())) {
                lucky = Math.max(lucky, e.getKey());
            }
        }
        return lucky;
    }
}

var findLucky = function(arr) {
    const counts = new Map();
    for (const x of arr) counts.set(x, (counts.get(x) || 0) + 1);
    let lucky = -1;
    for (const [num, freq] of counts.entries()) {
        if (num === freq) lucky = Math.max(lucky, num);
    }
    return lucky;
};
